import { Card, CardContent, Typography, Box, IconButton } from "@mui/material";
import IosShareIcon from "@mui/icons-material/IosShare";
import HighlightAltIcon from "@mui/icons-material/HighlightAlt";
import MyLocationIcon from "@mui/icons-material/MyLocation";
import { Link } from "react-router-dom";
import { useState } from "react";
import { URL } from "../../URL";
import CustomBTN from "../CustomButton/CustomBTN";
import AccountCircleIcon from "@mui/icons-material/AccountCircle";
import LikeView from "./LikeView";
function MarketplaceCard(props) {
  const [open, setOpen] = useState(false);
  const handleOpen = (_id) => {
    setOpen(true);
  };
  const videoType = ["mov", "mp4", "avi", "wmf", "flv", "webm"];
  const {
    locations,
    id,
    name,
    filelink,
    Image,
    file,
    user,
    productTotalPrice,
    userlikeviews,
    howManyViews,
    paidStatusContract,
  } = props;
  const result = file?.split(".");
  let fileType = result?.pop();
  return (
    <>
      <Card
        sx={{
          backgroundColor: "background.secondary",
          minHeight: "500px",
          borderRadius: "15px",
        }}
      >
        <Box sx={{ position: "relative" }}>
          <Box
            sx={{
              position: "absolute",
              top: "10px",
              left: "13px",
              display: "flex",
            }}
          >
            <Typography
              sx={{
                fontSize: "20px",
                backgroundColor: "#3ACAB8",
                opacity: "",
                paddingX: "8px",
                paddingY: "5px",
                borderRadius: "10px",
                color: "white",
                textDecoration: "none",
              }}
            >
              {" "}
              nft
            </Typography>
          </Box>
          <Box sx={{ position: "absolute", top: "10px", right: "10px" }}>
            <HighlightAltIcon
              sx={{
                fontSize: "35px",
                color: "white",
                backgroundColor: "#3ACAB8",
                opacity: "",
                padding: "8px",
                borderRadius: "10px",
              }}
            />
          </Box>
          <Box
            sx={{
              position: "absolute",
              bottom: "10px",
              left: "10px",
              cursor: "pointer",
            }}
          >
            <Link
              to={`/Bmap/${locations?.lang}/${locations?.long}`}
              style={{ color: "white" }}
            >
              <MyLocationIcon
                sx={{
                  fontSize: "35px",
                  backgroundColor: "#3ACAB8",
                  opacity: "",
                  padding: "8px",
                  borderRadius: "10px",
                }}
              />
            </Link>
          </Box>
          <Box sx={{ position: "absolute", top: "77%", right: 0 }}>
            <IconButton
              color="white"
              onClick={() => {
                handleOpen(id);
              }}
            >
              <IosShareIcon
                sx={{
                  fontSize: "35px",
                  color: "white",
                  backgroundColor: "#3ACAB8",
                  opacity: "",
                  padding: "8px",
                  borderRadius: "10px",
                }}
              />
            </IconButton>
          </Box>
          <Box
            sx={(theme) => ({
              boxShadow:
                theme.palette.mode === "light"
                  ? "rgb(242,231,231) 10px 10px 20px 22px inset, rgb(242,231,231) 10px 18px 36px 28px inset"
                  : "rgb(21 0 47 / 60%) 10px 10px 20px 22px inset, rgb(21 0 47 / 60%) 10px 18px 36px 28px inset",
              backgroundImage:
                file || filelink
                  ? `url(${URL}/upload/${file})` || `url(${filelink})`
                  : `url(${URL}/upload/${Image})`,
              backgroundPosition: "center",
              backgroundSize: "cover",
              height: "250px",
              width: "100%",
            })}
          >
            {videoType?.includes(fileType) ? (
              <video
                src={`${URL}/upload/${file}`}
                width="500"
                height="260"
                marginRight="50px"
                controls="controls"
                autoplay="false"
              />
            ) : null}
          </Box>
        </Box>

        <CardContent sx={{ m: { xs: 0 } }}>
          <Typography gutterBottom sx={{ pb: 1 }} variant="h6" component="h2">
            {name}
          </Typography>
          <Box
            sx={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <Typography sx={{ fontSize: "22px" }}> Price</Typography>
            <Typography component="p" sx={{ fontSize: "22px" }}>
              {productTotalPrice ? productTotalPrice + "$" : "0"}
            </Typography>
          </Box>

          <LikeView userlikeviews={userlikeviews} howManyViews={howManyViews} />
          <Box
            sx={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <Typography
              sx={{ fontSize: "1rem", color: "gray", fontWeight: 700 }}
            >
              {/* this is the user */}
              user
            </Typography>

            <Box
              sx={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                color: "gray",

              }}
            >
              <Typography component="p" sx={{ fontSize: "10px", mr: 1, maxWidth: "120px", overflow: "hidden" }}>
                {user?.username ? user?.username : "User name"}
              </Typography>
              {user?.profileImage ? (
                <Box>
                  <img
                    src={`${URL}/upload/${user?.profileImage}`}
                    alt=""
                    style={{
                      width: "35px",
                      height: "35px",
                      borderRadius: "50%",
                    }}
                  />
                </Box>
              ) : (
                <Box>
                  <AccountCircleIcon
                    style={{ width: "35px", height: "35px", borderRadius: "50%" }}
                  />
                </Box>
              )}
            </Box>
          </Box>
          <Box
            sx={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "centers",
            }}
          >
            <Typography
              component="p"
              sx={{ fontSize: "1rem", color: "gray", fontWeight: 700 }}
            >
              status
            </Typography>
            <Typography
              color={paidStatusContract ? "green" : "red"}
              component="p"
              sx={{ fontSize: "12px", ml: 1, mt: 1, fontWeight: 700 }}
            >
              {paidStatusContract ? "Mint succes" : "pending"}
            </Typography>
          </Box>

          <Link
            to={`/nftDetail/${id}`}
            style={{ textDecoration: "none", width: "100%" }}
          >
            <CustomBTN text="view Detail" />
          </Link>
        </CardContent>
      </Card>
    </>
  );
}
export default MarketplaceCard;
