import { Box, Grid, IconButton, Tooltip, Typography } from "@mui/material";
import * as React from "react";
import Card from "@mui/material/Card";
import CardContent from "@mui/material/CardContent";
import Button from "@mui/material/Button";
import profile from "../../../images/auther.PNG";
import EditIcon from "@mui/icons-material/Edit";
import KeyboardBackspaceIcon from "@mui/icons-material/KeyboardBackspace";
import { useNavigate } from "react-router-dom";
import EditProfile from "./EditeProfile";
import { useSelector } from "react-redux";
import { URL } from "../../../URL";
import PopUp from "../userWallet/popup";
import { profilestyle } from "./Profilecss/Customstyle";
export const ProfileHeader = () => {
  const { ceilSlice } = useSelector((state) => state);
  const { userdetails } = ceilSlice;
  const navigate = useNavigate();
  const [open, setOpen] = React.useState(false);
  function modalClose(value) {
    setOpen(value);
  }
  return (
    <>
      {open && <EditProfile open={open} modalFunc={modalClose} />}
      <Box sx={{ width: "100%", mx: "auto", mt: { xs: 1, md: 10 } }}>
        <Button
          onClick={() => {
            navigate(-1);
          }}
          variant="outlined"
          sx={{ border: "1px solid white", ml: 5, mb: 1 }}
          startIcon={<KeyboardBackspaceIcon />}
        >
          Go back
        </Button>
        <Card
          sx={{
            maxWidth: "95%",
            mx: "auto",
            borderRadius: "15px",
            mt: 3,
            "& .css-46bh2p-MuiCardContent-root": { padding: 0 },
            backgroundColor: "background.secondary",
            boxShadow: 2,
            height: "500px",
          }}
        >
          <Box
            sx={{
              position: "relative",
              backgroundImage: userdetails?.banner
                ? `url(${URL}/upload/${userdetails?.banner})`
                : `url("https://img.freepik.com/free-vector/technology-earth-digital-global-background_1017-31182.jpg?w=2000")`,
              height: "300px",
              backgroundSize: "cover",
              backgroundPosition: "top",
              backgroundRepeat: "no-repeat",
            }}
          >
            <Box
              sx={{
                position: "absolute",
                top: "190px",
                textAlign: "center",
                left: "50%",
                transform: "translate(-50%, 20%)",
              }}
            >
              {userdetails?.profileImage ? (
                <img
                  src={`${URL}/upload/${userdetails?.profileImage}`}
                  alt=""
                  style={profilestyle}
                />
              ) : (
                <img src={profile} style={profilestyle} alt="" />
              )}

              <Typography
                sx={{
                  fontSize: "15px",
                  fontWeight: "700",
                }}
              >
                {userdetails?.name ? userdetails?.name : "user name"}
              </Typography>
            </Box>
            {/* <ButtonBase
            sx={{
              position: "absolute",
              bottom: "-15px",
              right: { xs: "10px", md: "40px", lg: "60px" },
              px: 4,
              py: 1,
              backgroundColor: "black",
              color: "white",
              borderRadius: "15px",
            }}
          >
            folllow
          </ButtonBase> */}
          </Box>

          <CardContent>
            <Grid
              container
              display="flex"
              justifyContent="flex-end"
              alignItems="center"
            >
              <Grid
                item
                xs={12}
                md={7}
                sx={{
                  pl: { xs: 0, sm: 3, md: 7, lg: 3 },
                  mt: { xs: 12, md: 1 },
                  // border:"1px solid white"
                }}
              >
                <Box>
                  {/* <Typography>
                Join astronomers as they enter the final lap in a race to find a planet capable of sustaining life, a world like ours, the next Earth. See the launch of Frances CoRot and Americas Kepler missions, and the smoking hot worlds they
                </Typography> */}
                </Box>

                <Box sx={{ display: "flex", justifyContent: "flex-end" }}>
                  <Box
                    sx={{ pr: 4, pb: 1, display: "flex", alignItems: "center" }}
                  >
                    {/* <Link to="/userwallet">
                      <Tooltip title="wallet" placement="top">
                        <IconButton sx={{ color: "white", fontSize: "40px" }}>
                          <WalletIcon fontSize="large" />
                        </IconButton>
                      </Tooltip>
                    </Link> */}
                    <Tooltip title="Edit" placement="top">
                      <IconButton
                        sx={{
                          borderRadius: "5px",
                          background:
                            "linear-gradient(90.1deg, #4F98D0 0.11%, #34D9B1 95.94%)",
                          mr: 1,
                          mt: 1.5,
                        }}
                        onClick={() => {
                          setOpen(true);
                        }}
                      >
                        <EditIcon fontSize="small" sx={{ color: "white" }} />
                      </IconButton>
                    </Tooltip>
                    <PopUp />
                  </Box>
                </Box>
              </Grid>
            </Grid>
          </CardContent>
        </Card>
      </Box>
    </>
  );
};
