import {
  AddCeil,
  Adduser,
  Allusers,
  AddfailNfts,
  FavouriteNfts,
} from "./Redux/Reducer";
import { useDispatch, useSelector } from "react-redux";
import React from "react";
import Bmap from "./Component/Bmap";
import {
  BrowserRouter as Router,
  Navigate,
  Route,
  Routes,
} from "react-router-dom";
import { fetchAlluser, getBuyCells, userfavoriteNfts } from "./Api/api";
import { URL } from "./URL";
import Emailverify from "./Component/Auth/Emailverify";
import { Units } from "./Component/units";
import { UserLeaderboard } from "./Component/userLeaderboard";
import { ConnectKitProvider } from "connectkit";
import { WagmiConfig } from "wagmi";
import ConnectWallet from "./ConnectButton/ConnectWallet";
import { client } from "./utils/Utiles";
import { Login } from "./Component/Auth/Login";
import { Register } from "./Component/Auth/Register";
import Loading from "./Loading/Loading.js";
import ContextAPI from "./ContextAPI/CreateContext";
import { Box, Hidden } from "@mui/material";
import Header from "./Component/navbar";
import Details from "./Component/detail/detail.jsx";
import { Sidebar } from "./Component/sidebar";
import { User } from "./Component/userDashbord/user";
import { UserWallet } from "./Component/userDashbord/userWallet/userWallet";
import { Profile } from "./Component/userDashbord/profile/profile";
import MarketplacePage from "./Component/MarketplaceCard/MarketplacePage";
import NftDetail from "./Component/userDashbord/profile/NftDetail";
import { AdminProfile } from "./Component/AdminDashbord/Profile/AdminProfile";
function App() {
  const dispatch = useDispatch();
  const { ceilSlice } = useSelector((state) => state);
  const { userdetails } = ceilSlice;
  const [loading, setLoading] = React.useState(false);

  const tokenVerfiy = async () => {
    try {
      // setLoading(true);
      await fetch(`${URL}/verifytoken`, {
        method: "POST",
        headers: {
          "x-access-token": localStorage.getItem("maptoken"),
        },
      })
        .then((response) => response.json())
        .then((data) => {
          data?.status === "ok" && dispatch(Adduser(data));
          if (data?.error) {
            dispatch(Adduser({}));
          }
          // setLoading(false);
        });
    } catch (error) {
      console.log("Token verify route", error);
      // setLoading(false);
    }
  };

  React.useEffect(() => {
    tokenVerfiy();
  }, []);

  React.useEffect(() => {
    async function fetchBuyceil() {
      // setLoading(true);
      let buyceilValue = await getBuyCells();
      let alluser = await fetchAlluser();
      dispatch(Allusers(alluser));
      dispatch(AddCeil(buyceilValue?.nfts));
      dispatch(AddfailNfts(buyceilValue?.failedNfts));
      // setLoading(false);
    }
    fetchBuyceil();
  }, []);

  return (
    <>
      <Box sx={{ maxWidth: "xl", mx: "auto" }}>
        <WagmiConfig client={client}>
          <ContextAPI>
            <ConnectKitProvider theme="midnight" mode="dark">
              <Router>
                <Hidden mdUp>
                  <Header>
                    <ConnectWallet />
                  </Header>
                </Hidden>
                <Routes>
                  <Route path="/" element={<Sidebar />}>
                    <Route index element={<Bmap />} />
                    <Route path="/Bmap/:lang/:long" element={<Bmap />} />
                    <Route path="/units" element={<Units />} />
                    <Route
                      path="/userLeaderboard"
                      element={<UserLeaderboard />}
                    />
                    <Route path="/marketplace" element={<MarketplacePage />} />
                    <Route path="/register" element={<Register />} />
                    <Route path="/login" element={<Login />} />
                    <Route path="/detail/:id" element={<Details />} />
                    <Route path="/user" element={<User />} />
                    <Route path="/userwallet" element={<UserWallet />} />
                    <Route
                      path="/profile"
                      element={
                        userdetails ? (
                          // userdetails?.role[0]?.includes("user") ? (
                          <Profile />
                        ) : (
                          // ) : (
                          //   <Navigate to="/login" />
                          // )
                          ""
                        )
                      }
                    />
                    <Route path="/Emailverify/:id" element={<Emailverify />} />
                    <Route path="/nftDetail/:id" element={<NftDetail />} />
                    {/* <Route
                      path="/nftMarketDetail/:id"
                      element={<NftMarketPlace />}
                    /> */}
                    <Route
                      path="/admin"
                      element={
                        userdetails ? (
                          // userdetails?.role[0]?.includes("admin") ? (
                          <AdminProfile />
                        ) : (
                          // ) : (
                          //   <Navigate to="/login" />
                          // )
                          ""
                        )
                      }
                    />
                  </Route>
                </Routes>
              </Router>

              {/* </Container> */}
            </ConnectKitProvider>
          </ContextAPI>
        </WagmiConfig>
        <Loading loading={loading} />
      </Box>
      {/* </Container> */}
    </>
  );
}

export default App;
